ValidationRule.errorConditionFormula:
OR(
    AND(
        ISPICKVAL(AXF_IG_PKL_GroupType__c, "CONSORTIUM"),
        ISBLANK(AXF_IG_DAT_AdjustmentAnniversary__c)
    ),
    AND(
        NOT(ISPICKVAL(AXF_IG_PKL_GroupType__c, "CONSORTIUM")),
        OR(
            NOT(ISBLANK(AXF_IG_DAT_AdjustmentAnniversary__c)),
            NOT(ISBLANK(AXF_IG_DAT_LastAdjustmentDate__c))
        )
    )
)
